--
-- Table structure for table `order_items`
--

DROP TABLE IF EXISTS `order_items`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `order_items` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `order_id` bigint unsigned NOT NULL,
  `product_id` bigint unsigned NOT NULL,
  `inventory_product_id` bigint unsigned DEFAULT NULL,
  `line_group_key` varchar(80) NOT NULL,
  `line_type` enum('sale','bonus','gift','exchange') NOT NULL DEFAULT 'sale',
  `commercial_mode` varchar(20) DEFAULT NULL,
  `capture_mode` enum('quantity','amount') NOT NULL DEFAULT 'quantity',
  `requested_amount` decimal(12,2) DEFAULT NULL,
  `quantity` decimal(12,3) NOT NULL,
  `unit_price` decimal(12,2) NOT NULL,
  `regular_price_reference` decimal(14,2) DEFAULT NULL,
  `wholesale_price_found` decimal(14,2) DEFAULT NULL,
  `applied_price` decimal(14,2) DEFAULT NULL,
  `price_origin` varchar(30) DEFAULT NULL,
  `wholesale_price_configuration_id` bigint unsigned DEFAULT NULL,
  `wholesale_price_list_id` bigint unsigned DEFAULT NULL,
  `wholesale_price_list_name` varchar(150) DEFAULT NULL,
  `sale_bonus_invoiced_value` decimal(14,2) DEFAULT NULL,
  `sale_bonus_percent_applied` decimal(5,2) DEFAULT NULL,
  `sale_bonus_value_applied` decimal(14,2) DEFAULT NULL,
  `sale_bonus_product_price_used` decimal(14,2) DEFAULT NULL,
  `sale_bonus_result_quantity` decimal(14,3) DEFAULT NULL,
  `tax_percent` decimal(5,2) NOT NULL,
  `line_subtotal` decimal(12,2) NOT NULL,
  `line_tax` decimal(12,2) NOT NULL,
  `line_total` decimal(12,2) NOT NULL,
  `commercial_value` decimal(12,2) NOT NULL DEFAULT '0.00',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_order_items_order_group_type` (`order_id`,`line_group_key`,`line_type`),
  KEY `idx_order_items_product` (`product_id`),
  KEY `idx_order_items_order` (`order_id`),
  KEY `idx_order_items_wholesale_configuration` (`wholesale_price_configuration_id`),
  KEY `idx_order_items_wholesale_list` (`wholesale_price_list_id`),
  KEY `idx_order_items_inventory_product` (`inventory_product_id`),
  CONSTRAINT `fk_order_items_inventory_product` FOREIGN KEY (`inventory_product_id`) REFERENCES `products` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_order_items_order` FOREIGN KEY (`order_id`) REFERENCES `orders` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_order_items_product` FOREIGN KEY (`product_id`) REFERENCES `products` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_order_items_wholesale_configuration` FOREIGN KEY (`wholesale_price_configuration_id`) REFERENCES `wholesale_product_prices` (`id`),
  CONSTRAINT `fk_order_items_wholesale_list` FOREIGN KEY (`wholesale_price_list_id`) REFERENCES `wholesale_price_lists` (`id`),
  CONSTRAINT `chk_order_items_amounts` CHECK (((`unit_price` >= 0) and (`tax_percent` >= 0) and (`tax_percent` <= 100) and (`line_subtotal` >= 0) and (`line_tax` >= 0) and (`line_total` >= 0))),
  CONSTRAINT `chk_order_items_price_origin` CHECK (((`price_origin` is null) or (`price_origin` in (_utf8mb4'regular',_utf8mb4'wholesale_general',_utf8mb4'customer_special')))),
  CONSTRAINT `chk_order_items_price_snapshot` CHECK ((((`regular_price_reference` is null) or (`regular_price_reference` > 0)) and ((`wholesale_price_found` is null) or (`wholesale_price_found` > 0)) and ((`applied_price` is null) or (`applied_price` > 0)))),
  CONSTRAINT `chk_order_items_quantity` CHECK ((`quantity` > 0)),
  CONSTRAINT `chk_order_items_sale_bonus_audit` CHECK ((((`sale_bonus_invoiced_value` is null) or (`sale_bonus_invoiced_value` > 0)) and ((`sale_bonus_percent_applied` is null) or (`sale_bonus_percent_applied` >= 0)) and ((`sale_bonus_value_applied` is null) or (`sale_bonus_value_applied` >= 0)) and ((`sale_bonus_product_price_used` is null) or (`sale_bonus_product_price_used` > 0)) and ((`sale_bonus_result_quantity` is null) or (`sale_bonus_result_quantity` > 0))))
) ENGINE=InnoDB AUTO_INCREMENT=249 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

