--
-- Table structure for table `packing_report_items`
--

DROP TABLE IF EXISTS `packing_report_items`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `packing_report_items` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `packing_report_id` bigint unsigned NOT NULL,
  `production_batch_output_id` bigint unsigned NOT NULL,
  `product_id` bigint unsigned NOT NULL,
  `counted_quantity` decimal(14,3) NOT NULL DEFAULT '0.000',
  `packed_quantity` decimal(14,3) NOT NULL DEFAULT '0.000',
  `damaged_quantity` decimal(14,3) NOT NULL DEFAULT '0.000',
  `missing_quantity` decimal(14,3) NOT NULL DEFAULT '0.000',
  `damage_reason` enum('production','oven','cut','packaging') DEFAULT NULL,
  `missing_reason` enum('count_difference','handling_loss','suspected_theft','other') DEFAULT NULL,
  `notes` varchar(255) DEFAULT NULL,
  `produced_quantity` decimal(14,3) NOT NULL DEFAULT '0.000',
  `found_quantity` decimal(14,3) NOT NULL DEFAULT '0.000',
  `shortage_quantity` decimal(14,3) NOT NULL DEFAULT '0.000',
  `surplus_quantity` decimal(14,3) NOT NULL DEFAULT '0.000',
  `reconciliation_status` enum('matched','shortage','surplus') DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_packing_report_output` (`packing_report_id`,`production_batch_output_id`),
  KEY `idx_packing_report_items_report` (`packing_report_id`),
  KEY `idx_packing_report_items_output` (`production_batch_output_id`),
  KEY `idx_packing_report_items_product` (`product_id`),
  KEY `idx_packing_report_items_reconciliation` (`reconciliation_status`),
  CONSTRAINT `fk_packing_items_output` FOREIGN KEY (`production_batch_output_id`) REFERENCES `production_batch_outputs` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_packing_items_product` FOREIGN KEY (`product_id`) REFERENCES `products` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
