DROP TABLE IF EXISTS `packing_reports`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `packing_reports` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `production_batch_id` bigint unsigned NOT NULL,
  `packer_employee_id` bigint unsigned NOT NULL,
  `packed_date` date NOT NULL,
  `notes` varchar(255) DEFAULT NULL,
  `created_by` bigint unsigned DEFAULT NULL,
  `client_request_key` varchar(100) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_packing_reports_client_request_key` (`client_request_key`),
  KEY `idx_packing_reports_batch` (`production_batch_id`),
  KEY `idx_packing_reports_packer` (`packer_employee_id`),
  KEY `idx_packing_reports_date` (`packed_date`),
  KEY `fk_packing_reports_created_by` (`created_by`),
  CONSTRAINT `fk_packing_reports_batch` FOREIGN KEY (`production_batch_id`) REFERENCES `production_batches` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_packing_reports_created_by` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_packing_reports_packer` FOREIGN KEY (`packer_employee_id`) REFERENCES `employees` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=45 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
