--
-- Table structure for table `production_batch_outputs`
--

DROP TABLE IF EXISTS `production_batch_outputs`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `production_batch_outputs` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `production_batch_id` bigint unsigned NOT NULL,
  `product_id` bigint unsigned NOT NULL,
  `expected_quantity` decimal(14,3) NOT NULL,
  `produced_quantity` decimal(14,3) NOT NULL,
  `baker_reported_by` bigint unsigned DEFAULT NULL,
  `baker_reported_at` timestamp NULL DEFAULT NULL,
  `counted_quantity` decimal(14,3) NOT NULL DEFAULT '0.000',
  `counted_by` bigint unsigned DEFAULT NULL,
  `counted_at` timestamp NULL DEFAULT NULL,
  `packed_quantity` decimal(14,3) NOT NULL DEFAULT '0.000',
  `damaged_quantity` decimal(14,3) NOT NULL DEFAULT '0.000',
  `missing_quantity` decimal(14,3) NOT NULL DEFAULT '0.000',
  `direct_delivered_quantity` decimal(14,3) NOT NULL DEFAULT '0.000',
  `packing_note` varchar(255) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_batch_outputs_batch_product` (`production_batch_id`,`product_id`),
  KEY `idx_batch_outputs_product` (`product_id`),
  KEY `idx_batch_outputs_baker_reported_by` (`baker_reported_by`,`baker_reported_at`),
  KEY `idx_batch_outputs_counted_by` (`counted_by`,`counted_at`),
  CONSTRAINT `fk_batch_outputs_baker_reported_by` FOREIGN KEY (`baker_reported_by`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_batch_outputs_batch` FOREIGN KEY (`production_batch_id`) REFERENCES `production_batches` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_batch_outputs_counted_by` FOREIGN KEY (`counted_by`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_batch_outputs_product` FOREIGN KEY (`product_id`) REFERENCES `products` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `chk_batch_outputs_qty` CHECK (((`expected_quantity` > 0) and (`produced_quantity` >= 0) and (`packed_quantity` >= 0) and (`damaged_quantity` >= 0)))
) ENGINE=InnoDB AUTO_INCREMENT=119 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
