--
-- Table structure for table `production_batches`
--

DROP TABLE IF EXISTS `production_batches`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `production_batches` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `branch_id` bigint unsigned NOT NULL,
  `recipe_id` bigint unsigned NOT NULL,
  `baker_employee_id` bigint unsigned NOT NULL,
  `produced_date` date NOT NULL,
  `batch_quantity` decimal(14,3) NOT NULL DEFAULT '1.000',
  `status` enum('pending_packaging','partially_packed','packed','cancelled') NOT NULL DEFAULT 'pending_packaging',
  `notes` varchar(255) DEFAULT NULL,
  `created_by` bigint unsigned DEFAULT NULL,
  `client_request_key` varchar(100) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_production_batches_client_request_key` (`client_request_key`),
  KEY `idx_production_batches_branch_date` (`branch_id`,`produced_date`),
  KEY `idx_production_batches_recipe` (`recipe_id`),
  KEY `idx_production_batches_baker` (`baker_employee_id`),
  KEY `idx_production_batches_status` (`status`),
  KEY `fk_production_batches_created_by` (`created_by`),
  CONSTRAINT `fk_production_batches_baker` FOREIGN KEY (`baker_employee_id`) REFERENCES `employees` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_production_batches_branch` FOREIGN KEY (`branch_id`) REFERENCES `branches` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_production_batches_created_by` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_production_batches_recipe` FOREIGN KEY (`recipe_id`) REFERENCES `recipes` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `chk_production_batches_qty` CHECK ((`batch_quantity` > 0))
) ENGINE=InnoDB AUTO_INCREMENT=57 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `production_batches`
--

