)
BEGIN
  DECLARE v_rows INT DEFAULT 0;

  IF p_status NOT IN ('active', 'inactive') THEN
    SET o_code = 0;
    SET o_message = 'estado de proveedor invalido';
    SET o_data_json = NULL;
