    SELECT 1 FROM suppliers WHERE tax_id = TRIM(p_tax_id) AND id <> p_supplier_id
  ) THEN
    SET o_code = 0;
    SET o_message = 'el tax_id del proveedor ya existe';
    SET o_data_json = NULL;
