/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_user_get_by_id`(
  IN p_user_id BIGINT UNSIGNED,
  OUT o_code INT,
  OUT o_message VARCHAR(255),
  OUT o_data_json LONGTEXT
)
BEGIN
  DECLARE v_exists INT DEFAULT 0;

  SELECT COUNT(*)
    INTO v_exists
  FROM users u
  WHERE u.id = p_user_id
    AND u.deleted_at IS NULL;

  IF v_exists = 0 THEN
    SET o_code = 0;
    SET o_message = 'usuario no encontrado';
    SET o_data_json = NULL;
  ELSE
    SET o_code = 1;
    SET o_message = 'usuario obtenido';

    SELECT JSON_OBJECT(
      'id', u.id,
      'username', u.username,
      'email', u.email,
      'full_name', u.full_name,
      'phone', u.phone,
      'status', u.status,
      'must_change_password', u.must_change_password,
      'last_login_at', u.last_login_at,
      'roles', IFNULL(
        (
          SELECT CONCAT('[', GROUP_CONCAT(JSON_QUOTE(r.code) ORDER BY r.code SEPARATOR ','), ']')
          FROM user_roles ur
          INNER JOIN roles r ON r.id = ur.role_id
          WHERE ur.user_id = u.id
        ),
        '[]'
      )
    )
    INTO o_data_json
    FROM users u
    WHERE u.id = p_user_id
      AND u.deleted_at IS NULL
    LIMIT 1;
  END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
